import sys
from sys import setrecursionlimit

def main():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())
    intervals = []
    for _ in range(M):
        s, t = map(int, input().split())
        if s > t:
            s, t = t, s
        intervals.append((s, t))
    queries = [tuple(map(int, input().split())) for _ in range(Q)]

    # Build graph: nodes are towns 1..N, edges are intervals (s,t) with s<t
    adj = [[] for _ in range(N + 1)]
    for idx, (s, t) in enumerate(intervals):
        adj[s].append((t, idx))
        adj[t].append((s, idx))

    # Iterative DFS to find cycles and assign parity (color) to nodes
    color = [-1] * (N + 1)
    parent_edge = [-1] * (N + 1)
    parent_node = [-1] * (N + 1)
    depth = [0] * (N + 1)
    in_cycle = [False] * M
    bad = [False] * M  # bad[i] = True if interval i is in an odd cycle

    for start in range(1, N + 1):
        if color[start] != -1:
            continue
        color[start] = 0
        stack = [(start, -1, 0)]  # (node, parent_edge, depth)
        while stack:
            u, pe, d = stack.pop()
            depth[u] = d
            for v, idx in adj[u]:
                if idx == pe:
                    continue
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    parent_edge[v] = idx
                    parent_node[v] = u
                    stack.append((v, idx, d + 1))
                else:
                    # Found a cycle (back edge or cross edge)
                    if not in_cycle[idx]:
                        # Mark all edges in the cycle
                        # The cycle is: u -> ... -> v (via tree path) + edge (u,v)
                        # We need to mark edges on path from u to v in the tree plus edge idx
                        # Use depth to climb up
                        x, y = u, v
                        # Mark edge idx
                        in_cycle[idx] = True
                        if color[u] == color[v]:
                            bad[idx] = True
                        # Climb up the deeper node
                        while depth[x] > depth[y]:
                            e = parent_edge[x]
                            if not in_cycle[e]:
                                in_cycle[e] = True
                                if color[u] == color[v]:
                                    bad[e] = True
                            x = parent_node[x]
                        while depth[y] > depth[x]:
                            e = parent_edge[y]
                            if not in_cycle[e]:
                                in_cycle[e] = True
                                if color[u] == color[v]:
                                    bad[e] = True
                            y = parent_node[y]
                        while x != y:
                            e = parent_edge[x]
                            if not in_cycle[e]:
                                in_cycle[e] = True
                                if color[u] == color[v]:
                                    bad[e] = True
                            x = parent_node[x]
                            e = parent_edge[y]
                            if not in_cycle[e]:
                                in_cycle[e] = True
                                if color[u] == color[v]:
                                    bad[e] = True
                            y = parent_node[y]

    # Precompute prefix sums of bad intervals
    prefix_bad = [0] * (M + 1)
    for i in range(M):
        prefix_bad[i + 1] = prefix_bad[i] + (1 if bad[i] else 0)

    # Answer queries
    out = []
    for l, r in queries:
        if prefix_bad[r] - prefix_bad[l - 1] == 0:
            out.append("Yes")
        else:
            out.append("No")
    print("\n".join(out))

