class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        offset = 1800
        size = 3601
        NEG = -1

        # dp[parity][alt_sum + offset] = max product
        dp = [[NEG] * size for _ in range(2)]
        dp[0][offset] = 1  # empty subsequence: length 0 (even), sum 0, product 1

        for x in nums:
            new_dp = [row[:] for row in dp]
            for parity in range(2):
                for s in range(size):
                    cur = dp[parity][s]
                    if cur == NEG:
                        continue
                    if parity == 0:
                        ns = s + x
                    else:
                        ns = s - x
                    if 0 <= ns < size:
                        nprod = cur * x
                        if nprod > limit:
                            nprod = limit + 1
                        np = parity ^ 1
                        if nprod > new_dp[np][ns]:
                            new_dp[np][ns] = nprod
            dp = new_dp

        ans = NEG
        if 0 <= k + offset < size:
            for parity in range(2):
                val = dp[parity][k + offset]
                if val != NEG and val <= limit:
                    # exclude empty subsequence case (product 1, sum 0, parity 0)
                    if not (parity == 0 and k == 0 and val == 1):
                        if val > ans:
                            ans = val
        # But we must be careful: a non-empty subsequence could also have product 1, sum 0, even length.
        # The exclusion above is too aggressive. Let's instead track emptiness properly.

        # Redo with empty tracking
        dp = [[NEG] * size for _ in range(2)]
        dp[0][offset] = 1
        empty_possible = True  # empty subsequence always exists initially

        # We need to know if a state is reachable by a non-empty subsequence.
        # Track separately: dp stores max product, and we track non-empty reachability.
        # Since product alone can't distinguish, track non-empty states.

        nonempty = [[False] * size for _ in range(2)]

        dp = [[NEG] * size for _ in range(2)]
        dp[0][offset] = 1

        for x in nums:
            new_dp = [row[:] for row in dp]
            new_ne = [row[:] for row in nonempty]
            for parity in range(2):
                for s in range(size):
                    cur = dp[parity][s]
                    if cur == NEG:
                        continue
                    is_ne = nonempty[parity][s] or True  # adding element makes it non-empty
                    if parity == 0:
                        ns = s + x
                    else:
                        ns = s - x
                    if 0 <= ns < size:
                        nprod = cur * x
                        if nprod > limit:
                            nprod = limit + 1
                        np = parity ^ 1
                        if nprod > new_dp[np][ns]:
                            new_dp[np][ns] = nprod
                            new_ne[np][ns] = True
                        elif nprod == new_dp[np][ns]:
                            new_ne[np][ns] = new_ne[np][ns] or True
            dp = new_dp
            nonempty = new_ne

        ans = NEG
        if 0 <= k + offset < size:
            for parity in range(2):
                if nonempty[parity][k + offset]:
                    val = dp[parity][k + offset]
                    if val != NEG and val <= limit:
                        if val > ans:
                            ans = val
        return ans

