def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    q = int(data[0])
    queries = list(map(int, data[1:1+q]))
    max_a = max(queries) if queries else 0

    limit = int(max_a ** 0.5) + 2
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            sieve[start:limit+1:i] = b"\x00" * (((limit - start) // i) + 1)
    primes = [i for i, v in enumerate(sieve) if v]

    nums = set()
    for p in primes:
        pp = p * p
        if pp > max_a:
            break
        for q_ in primes:
            if q_ == p:
                continue
            qq = q_ * q_
            if pp * qq > max_a:
                break
            base = pp * qq
            val = base
            while val <= max_a:
                nums.add(val)
                val *= base

    arr = sorted(nums)
    out = []
    for a in queries:
        idx = bisect.bisect_right(arr, a) - 1
        out.append(str(arr[idx]))
    sys.stdout.write("\n".join(out) + "\n")

