class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(n):
            prefix_nums[i + 1] = prefix_nums[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                # Subarray nums[j..i-1] is the (number of subarrays so far + 1)-th subarray
                # But we need to track the subarray index. Let's redefine:
                # dp[i] = min cost to partition first i elements
                # If last subarray is nums[j..i-1], and it's the m-th subarray,
                # its cost is (prefix_nums[i] + k*m) * (prefix_cost[i] - prefix_cost[j])
                # We need to know m, which is the number of subarrays in dp[j] partition.
                # So we need dp[i][m] = min cost to partition first i elements into m subarrays.
                pass

        # Redefine: dp[i][m] = min cost to partition first i elements into m subarrays
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for m in range(1, i + 1):
                for j in range(m - 1, i):
                    # Last subarray is nums[j..i-1], it's the m-th subarray
                    cost_val = (prefix_nums[i] + k * m) * (prefix_cost[i] - prefix_cost[j])
                    if dp[j][m - 1] != INF:
                        dp[i][m] = min(dp[i][m], dp[j][m - 1] + cost_val)

        return min(dp[n][1:])

