def solve():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()
    T = input().strip()

    # Build mapping from each character in S to character in T
    mapping = {}
    for s, t in zip(S, T):
        if s in mapping:
            if mapping[s] != t:
                print(-1)
                return
        else:
            mapping[s] = t

    # Check if any target character is "free" (not used as a source in mapping)
    used_sources = set(mapping.keys())
    free_chars = [chr(ord('a') + i) for i in range(26) if chr(ord('a') + i) not in used_sources]

    # Build graph of needed transformations (ignore identity mappings)
    graph = {}
    for s, t in mapping.items():
        if s != t:
            graph[s] = t

    # Count minimum operations
    visited = set()
    operations = 0

    for node in graph:
        if node in visited:
            continue
        # Traverse the chain/cycle starting from node
        curr = node
        path = []
        while curr in graph and curr not in visited:
            visited.add(curr)
            path.append(curr)
            curr = graph[curr]

        if curr in graph and curr in path:
            # Found a cycle
            cycle_start = path.index(curr)
            cycle = path[cycle_start:]
            non_cycle = path[:cycle_start]
            # Non-cycle part: each edge is one operation
            operations += len(non_cycle)
            # Cycle: need len(cycle) + 1 operations if no free char, else len(cycle)
            if free_chars:
                operations += len(cycle)
            else:
                operations += len(cycle) + 1
        else:
            # No cycle, just a chain
            operations += len(path)

    print(operations)

