from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def count_ops(n: int) -> int:
            # Sum of ceil(d/2) for all numbers from 1 to n, where d is the number of base-4 digits
            if n <= 0:
                return 0
            total = 0
            d = 1
            start = 1
            while start <= n:
                end = min(n, 4 * start - 1)
                cnt = end - start + 1
                total += cnt * ((d + 1) // 2)
                start *= 4
                d += 1
            return total

        ans = 0
        for l, r in queries:
            total = count_ops(r) - count_ops(l - 1)
            # The minimum operations is ceil(total / 2)
            ans += (total + 1) // 2
        return ans

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, tight: bool, started: bool, digit_sum: int, digit_prod: int) -> int:
                if pos == length:
                    if not started:
                        return 0
                    if digit_sum == 0:
                        return 0
                    return 1 if digit_prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)
                    new_sum = digit_sum + d
                    if not started and d == 0:
                        new_prod = digit_prod
                    else:
                        new_prod = digit_prod * d
                    total += dp(pos + 1, new_tight, new_started, new_sum, new_prod)
                return total

            return dp(0, True, False, 0, 1)

        return count_upto(r) - count_upto(l - 1)

import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for u, v in edges:
        adj[u].append(v)

    # Compute shortest path distances from 1 to all nodes (unweighted)
    dist_from_1 = [-1] * N
    dist_from_1[0] = 0
    q = deque([0])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist_from_1[v] == -1:
                dist_from_1[v] = dist_from_1[u] + 1
                q.append(v)

    # Compute shortest path distances from all nodes to N (unweighted)
    dist_to_N = [-1] * N
    dist_to_N[N - 1] = 0
    q = deque([N - 1])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist_to_N[v] == -1:
                dist_to_N[v] = dist_to_N[u] + 1
                q.append(v)

    # Check if a given distance d is achievable
    def is_achievable(d):
        # We need to select K edges such that every path from 1 to N has at least d edges with weight 1
        # This is equivalent to finding a cut of size K that intersects every path at least d times
        # We can model this as a min-cut problem in a layered graph

        # Create a graph with d layers
        # Node (u, i) represents being at vertex u with i edges of weight 1 used so far
        # We want to find the minimum number of edges to select such that all paths from (1, 0) to (N, d-1) are cut

        # Build the graph
        graph = {}
        node_id = 0
        node_map = {}

        # Add source and sink
        source = node_id
        node_id += 1
        sink = node_id
        node_id += 1

        # Add nodes for each layer
        for i in range(d):
            for u in range(N):
                if dist_from_1[u] != -1 and dist_to_N[u] != -1 and dist_from_1[u] + dist_to_N[u] >= d - 1 - i:
                    node_map[(u, i)] = node_id
                    node_id += 1

        # Add edges
        for i in range(d):
            for u in range(N):
                if (u, i) not in node_map:
                    continue
                u_id = node_map[(u, i)]

                # Connect to source if this is the first layer and u is reachable from 1
                if i == 0 and dist_from_1[u] == 0:
                    if source not in graph:
                        graph[source] = {}
                    graph[source][u_id] = float('inf')

                # Connect to sink if this is the last layer and u can reach N
                if i == d - 1 and dist_to_N[u] == 0:
                    if u_id not in graph:
                        graph[u_id] = {}
                    graph[u_id][sink] = float('inf')

                # Add edges to next layer
                for v in adj[u]:
                    if (v, i + 1) in node_map:
                        v_id = node_map[(v, i + 1)]
                        if u_id not in graph:
                            graph[u_id] = {}
                        graph[u_id][v_id] = 1  # Cost 1 to select this edge

        # Add reverse edges for residual graph
        for u in list(graph.keys()):
            for v in list(graph[u].keys()):
                if v not in graph:
                    graph[v] = {}
                if u not in graph[v]:
                    graph[v][u] = 0

        # Find min cut using max flow (Dinic's algorithm)
        def bfs():
            level = {source: 0}
            q = deque([source])
            while q:
                u = q.popleft()
                for v, capacity in graph.get(u, {}).items():
                    if capacity > 0 and v not in level:
                        level[v] = level[u] + 1
                        q.append(v)
            return level if sink in level else None

        def dfs(u, flow, level, iter_):
            if u == sink:
                return flow
            for v, capacity in iter_[u]:
                if capacity > 0 and level.get(v, -1) == level[u] + 1:
                    d = dfs(v, min(flow, capacity), level, iter_)
                    if d > 0:
                        graph[u][v] -= d
                        graph[v][u] += d
                        return d
            return 0

        max_flow = 0
        while True:
            level = bfs()
            if not level:
                break
            iter_ = {u: iter(graph[u].items()) for u in graph}
            while True:
                f = dfs(source, float('inf'), level, iter_)
                if f == 0:
                    break
                max_flow += f

        return max_flow <= K

    # Binary search for the maximum achievable distance
    low, high = 0, N
    while low < high:
        mid = (low + high + 1) // 2
        if is_achievable(mid):
            low = mid
        else:
            high = mid - 1

    print(low)

