class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['a'] * L
        fixed = [False] * L

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]
                    fixed[pos] = True

        # Check all 'F' constraints
        for i in range(n):
            if str1[i] == 'F':
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    # Find rightmost non-fixed position in window [i, i+m-1]
                    changed = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if not fixed[pos]:
                            word[pos] = 'b'
                            changed = True
                            break
                    if not changed:
                        return ""

        return ''.join(word)

