                    heapq.heappush(pq, (d + 1, v, 1))
        # Reverse all edges
        if dist[u][1 - state] > d + X:
            dist[u][1 - state] = d + X
            heapq.heappush(pq, (d + X, u, 1 - state))

    print(min(dist[N][0], dist[N][1]))

