from typing import List
from math import lcm
from itertools import combinations

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        # Precompute LCMs for all non-empty subsets of target
        subset_lcm = {}
        for mask in range(1, 1 << m):
            l = 1
            for i in range(m):
                if mask >> i & 1:
                    l = lcm(l, target[i])
            subset_lcm[mask] = l

        # For each number in nums, compute the minimum cost to satisfy each subset
        # cost[mask] = min over nums of (ceil(lcm / num) * lcm - num)
        INF = float('inf')
        cost = [INF] * (1 << m)
        cost[0] = 0
        for num in nums:
            for mask in range(1, 1 << m):
                l = subset_lcm[mask]
                # Smallest multiple of l that is >= num
                multiple = ((num + l - 1) // l) * l
                c = multiple - num
                if c < cost[mask]:
                    cost[mask] = c

        # DP over subsets: dp[mask] = min cost to satisfy all targets in mask
        dp = [INF] * (1 << m)
        dp[0] = 0
        for mask in range(1, 1 << m):
            # Try assigning a subset to one number, rest handled recursively
            sub = mask
            while sub:
                if cost[sub] != INF and dp[mask ^ sub] != INF:
                    dp[mask] = min(dp[mask], dp[mask ^ sub] + cost[sub])
                sub = (sub - 1) & mask

        return dp[(1 << m) - 1]

