    g = [[0] * W for _ in range(H)]
    g[H-1][W-1] = A[H-1][W-1]
    for j in range(W-2, -1, -1):
        g[H-1][j] = g[H-1][j+1] * A[H-1][j] % MOD
    for i in range(H-2, -1, -1):
