class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def canAchieve(maxLen: int) -> bool:
            # Try both starting characters
            for startChar in ['0', '1']:
                ops = 0
                runLength = 0
                currentChar = startChar

                for i in range(n):
                    if s[i] == currentChar:
                        runLength += 1
                        if runLength > maxLen:
                            # Need to flip this character
                            ops += 1
                            currentChar = '1' if currentChar == '0' else '0'
                            runLength = 1
                    else:
                        # Character matches what we want after flip
                        currentChar = '1' if currentChar == '0' else '0'
                        runLength = 1

                    if ops > numOps:
                        break

                if ops <= numOps:
                    return True

            return False

        # Binary search on the answer
        left, right = 1, n
        result = n

        while left <= right:
            mid = (left + right) // 2
            if canAchieve(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result

