from typing import List
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)

        # Map each value to its index (values are unique)
        idx = {v: i for i, v in enumerate(nums)}

        # For each possible lcm value m <= threshold, collect indices of
        # numbers in nums that divide m. All such numbers are pairwise
        # connected (their lcm divides m, hence <= threshold), so union them.
        divisors = defaultdict(list)
        for i, v in enumerate(nums):
            for m in range(v, threshold + 1, v):
                divisors[m].append(i)

        for m, lst in divisors.items():
            first = lst[0]
            for other in lst[1:]:
                dsu.union(first, other)

        return dsu.count
